   360	// killPinnedMarkedProcess signals pid only through a pidfd opened on it,
   361	// after the environment read through that same pinned process still holds
   362	// entry.
   363	func killPinnedMarkedProcess(pid int, entry []byte) error {
   364		fd, err := unix.PidfdOpen(pid, 0)
   365		if errors.Is(err, unix.ESRCH) {
   366			return nil
   367		}
   368		if err != nil {
   369			return fmt.Errorf("process %d could not be pinned: %w", pid, err)
   370		}
   371		defer unix.Close(fd)
   372		// The pidfd names one process for its lifetime; if pid was reused before
   373		// it was opened, the new process does not carry this run's entry.
   374		marked, err := reviewProcessMarked(pid, entry)
   375		if reviewProcessGoneErr(err) || err == nil && !marked {
   376			return nil
   377		}
   378		if err != nil {
   379			return fmt.Errorf("process %d could not be inspected: %w", pid, err)
   380		}
   381		if err := unix.PidfdSendSignal(fd, unix.SIGKILL, nil, 0); err != nil && !errors.Is(err, unix.ESRCH) {
   382			return fmt.Errorf("process %d could not be ended: %w", pid, err)
   383		}
   384		return nil
   385	}
