   387	func reviewProcessMarked(pid int, entry []byte) (bool, error) {
   388		environ, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "environ"))
   389		if err != nil {
   390			return false, err
   391		}
   392		for _, kv := range bytes.Split(environ, []byte{0}) {
   393			if bytes.Equal(kv, entry) {
   394				return true, nil
   395			}
   396		}
   397		return false, nil
   398	}
