   400	func reviewProcessOwner(pid int) (int, error) {
   401		info, err := os.Stat(filepath.Join("/proc", strconv.Itoa(pid)))
   402		if err != nil {
   403			return 0, err
   404		}
   405		st, ok := info.Sys().(*syscall.Stat_t)
   406		if !ok {
   407			return 0, fmt.Errorf("process %d owner unavailable", pid)
   408		}
   409		return int(st.Uid), nil
   410	}
