   424	func reviewProcessZombie(pid int) (bool, error) {
   425		raw, err := os.ReadFile(filepath.Join("/proc", strconv.Itoa(pid), "stat"))
   426		if err != nil {
   427			return false, err
   428		}
   429		// The state follows the parenthesised command name.
   430		if i := bytes.LastIndexByte(raw, ')'); i >= 0 && i+2 < len(raw) {
