 57	// Verify the covered Linux group after SIGKILL. Zombies have terminated and
 58	// cannot hold pipes; reaping is their parent's duty. Other Unix ports currently
 59	// report signal delivery only and cannot require verified group termination.
 60	func verifyReviewProcessGroup(pid int) error {
 61		if runtime.GOOS != "linux" {
 62			return nil
 63		}
 64		deadline := time.Now().Add(time.Second)
 65		for {
 66			entries, err := os.ReadDir("/proc")
 67			if err != nil {
 68				return fmt.Errorf("process-group termination could not be observed")
 69			}
 70			if len(entries) > 100000 {
 71				return fmt.Errorf("process inventory exceeds coverage")
 72			}
 73			alive := false
 74			for _, entry := range entries {
 75				if _, err := strconv.Atoi(entry.Name()); err != nil {
 76					continue
 77				}
 78				raw, err := os.ReadFile("/proc/" + entry.Name() + "/stat")
 79				if processGone(err) {
 80					continue
 81				}
 82				if err != nil {
 83					return fmt.Errorf("process inventory incomplete")
 84				}
 85				end := strings.LastIndex(string(raw), ")")
 86				if end < 0 {
 87					return fmt.Errorf("process inventory malformed")
 88				}
 89				fields := strings.Fields(string(raw[end+1:]))
 90				if len(fields) < 3 {
 91					return fmt.Errorf("process inventory malformed")
 92				}
 93				group, err := strconv.Atoi(fields[2])
 94				if err != nil {
 95					return fmt.Errorf("process group malformed")
 96				}
 97				if group == pid && fields[0] != "Z" && fields[0] != "X" {
 98					alive = true
 99					break
100				}
101			}
102			if !alive {
103				return nil
104			}
105			if time.Now().After(deadline) {
106				return fmt.Errorf("process group remained alive after termination")
107			}
108			time.Sleep(10 * time.Millisecond)
109		}
110	}
