    76	// reapShimSubtree ends and reaps every child of the shim, including the
    77	// orphans its subreaper status adopted, until none is left.
    78	func reapShimSubtree() ([]string, error) {
    79		self := os.Getpid()
    80		var ended []string
    81		seen := map[int]bool{}
    82		deadline := time.Now().Add(reviewReapWait)
