    84			dirs, err := os.ReadDir("/proc")
    85			if err != nil {
    86				return ended, fmt.Errorf("the run's processes could not be listed: %w", err)
    87			}
    88			children := 0
    89			for _, d := range dirs {
    90				pid, err := strconv.Atoi(d.Name())
    91				if err != nil || pid == self {
    92					continue
    93				}
    94				st, err := readShimProcStat(pid)
    95				if reviewProcessGoneErr(err) {
    96					continue
    97				}
    98				if err != nil {
    99					return ended, fmt.Errorf("process %d could not be inspected: %w", pid, err)
   100				}
   101				if st.ppid != self {
   102					continue
   103				}
   104				children++
   105				if !st.zombie {
   106					if !seen[pid] {
   107						seen[pid] = true
   108						ended = append(ended, strconv.Itoa(pid))
   109					}
   110					if err := killPinnedChild(pid, self); err != nil {
   111						return ended, err
   112					}
   113				}
   114			}
