   116				pid, err := unix.Wait4(-1, nil, unix.WNOHANG, nil)
   117				if pid <= 0 || err != nil {
   118					break
   119				}
   120			}
   121			if children == 0 {
   122				return ended, nil
   123			}
   124			if time.Now().After(deadline) {
   125				return ended, fmt.Errorf("%d process(es) of the run could not be ended", children)
   126			}
   127			time.Sleep(20 * time.Millisecond)
   128		}
   129	}
