   136	func readShimProcStat(pid int) (shimProcStat, error) {
   137		raw, err := os.ReadFile("/proc/" + strconv.Itoa(pid) + "/stat")
   138		if err != nil {
   139			return shimProcStat{}, err
   140		}
   141		text := string(raw)
   142		end := strings.LastIndexByte(text, ')')
   143		if end < 0 {
   144			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   145		}
   146		f := strings.Fields(text[end+1:])
   147		if len(f) < 2 {
   148			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   149		}
   150		ppid, err := strconv.Atoi(f[1])
   151		if err != nil {
   152			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   153		}
   154		return shimProcStat{ppid: ppid, zombie: f[0] == "Z"}, nil
   155	}
