   157	// killPinnedChild signals pid through a pidfd while it is still a child of
   158	// parent: a pid reused by an unrelated process is never signalled.
   159	func killPinnedChild(pid, parent int) error {
   160		fd, err := unix.PidfdOpen(pid, 0)
   161		if errors.Is(err, unix.ESRCH) {
   162			return nil
   163		}
   164		if err != nil {
   165			return fmt.Errorf("process %d could not be pinned: %w", pid, err)
   166		}
