   170			return nil
   171		}
   172		if err != nil {
   173			return fmt.Errorf("process %d could not be inspected: %w", pid, err)
   174		}
   175		if err := unix.PidfdSendSignal(fd, unix.SIGKILL, nil, 0); err != nil && !errors.Is(err, unix.ESRCH) {
   176			return fmt.Errorf("process %d could not be ended: %w", pid, err)
   177		}
   178		return nil
   179	}
