   162	// recordedAttemptRun finds the latest run recorded for attempt a.
   163	func (s Store) recordedAttemptRun(a DelegatedReviewAttempt) (ReviewRun, bool, error) {
   164		runs, lost, err := s.ReadReviewRuns(a.BundleID)
   165		if err != nil {
   166			return ReviewRun{}, false, err
   167		}
   168		if len(lost) > 0 {
   169			// An unreadable run may be this release's: the history is unknown,
   170			// and the release does not write another (review round 4, N3).
   171			return ReviewRun{}, false, fmt.Errorf("the run history of %s is incomplete, so an earlier release cannot be ruled out: %s", a.BundleID, strings.Join(lost, "; "))
   172		}
   173		var latest *ReviewRun
   174		for i := range runs {
   175			if runs[i].AttemptID == a.AttemptID && (latest == nil || runs[i].EndedAt > latest.EndedAt) {
   176				latest = &runs[i]
   177			}
   178		}
   179		if latest == nil {
   180			return ReviewRun{}, false, nil
   181		}
   182		return *latest, true, nil
   183	}
